    {
      "path": "dsh-preset/tools/gzhflow-tools.mjs",
      "content": "/**\n * gzhflow-tools — gzhflow 六阶段质检门脚本的 DSH 工具包装层。\n *\n * 零外部依赖（preset 相对路径在用户 home 下解析不到 @deepseek-ai/*），只用 node: 内建。\n * 脚本本体在仓库 scripts/（纯 stdlib CLI），本模块只做参数 → ctx.subprocess 调用 → 结构化结果。\n *\n * DSH preset 模块契约：export const name / inject / apply(ctx, config)。\n * 工具统一返回 { exit_code, output, stderr }；output = 脚本 stdout（含 FAIL/WARN 明细）。\n */\nimport { fileURLToPath } from 'node:url'\nimport { join } from 'node:path'\nimport { readFileSync, existsSync } from 'node:fs'\n\nexport const name = 'gzhflow-tools'\nexport const inject = ['tools', 'credentials', 'subprocess']\n\n/**\n * 解析 gzhflow 仓库根（含 scripts/）。部署形态有两种：\n *   1. 仓库内开发（junction 或直接路径）：本文件位于 <repo>/dsh-preset/tools/，向上两级即仓库根。\n *   2. 拷贝安装（DSH 预设发现不跟 junction，需真实目录）：安装器把 dsh-preset/ 拷到\n *      <dshHome>/.agent-presets/gzhflow/ 并在同目录写 .gzhflow-repo 指针文件。\n * 解析优先级：env GZHFLOW_REPO > 指针文件 > 仓库布局探测。找不到时抛错（runScript 会转成友好返回）。\n */\nfunction resolveRepoRoot() {\n  const envRepo = process.env.GZHFLOW_REPO\n  if (envRepo) return envRepo\n  const moduleDir = fileURLToPath(new URL('.', import.meta.url))\n  const pointer = join(moduleDir, '..', '.gzhflow-repo')\n  try {\n    const fromPointer = readFileSync(pointer, 'utf8').trim()\n    if (fromPointer && existsSync(join(fromPointer, 'scripts'))) return fromPointer\n  } catch { /* 指针文件缺失 = 仓库内布局，走下方探测 */ }\n  const repo = fileURLToPath(new URL('../../', import.meta.url))\n  if (existsSync(join(repo, 'scripts'))) return repo\n  throw new Error(\n    'gzhflow-tools: 无法定位仓库根（scripts/ 不存在）。' +\n    '若为拷贝安装请检查 <preset>/.gzhflow-repo 指针文件，或设环境变量 GZHFLOW_REPO。'\n  )\n}\n\nconst REPO_ROOT = resolveRepoRoot()\nconst SCRIPTS_DIR = join(REPO_ROOT, 'scripts')\n\n/**\n * 极简读取仓库 config/workflow.yaml 的 image_backend 段（base_url/model/api_key_env）。\n * 纯行扫描，零依赖；文件缺失/解析失败返回空对象（调用方给引导信息）。\n */\nfunction readImageBackendConfig() {\n  const cfgPath = join(REPO_ROOT, 'config', 'workflow.yaml')\n  let text\n  try {\n    text = readFileSync(cfgPath, 'utf8')\n  } catch {\n    return {}\n  }\n  const out = {}\n  let inBackend = false\n  for (const line of text.split(/\\r?\\n/)) {\n    const trimmed = line.trim()\n    if (!trimmed || trimmed.startsWith('#')) continue\n    if (/^image_backend\\s*:/.test(trimmed)) { inBackend = true; continue }\n    if (/^\\S/.test(trimmed)) inBackend = false // 顶层新键，退出 image_backend 段\n    if (!inBackend) continue\n    const m = /^(base_url|model|api_key_env)\\s*:\\s*\"?([^\"\\s]+)\"?/.exec(trimmed)\n    if (m) out[m[1]] = m[2]\n  }\n  return out\n}\n\n/** 最小 spec → JSON Schema 编译器（preset 环境无法 import defineTool）。 */\nfunction toJsonSchema(spec) {\n  const properties = {}\n  const required = []\n  for (const [key, meta] of Object.entries(spec || {})) {\n    const prop = { type: meta.type }\n    if (Array.isArray(meta.enum)) prop.enum = meta.enum\n    if (meta.description) prop.description = meta.description\n    properties[key] = prop\n    if (meta.required) required.push(key)\n  }\n  return { type: 'object', properties, required, additionalProperties: false }\n}\n\n/** 跑一个 scripts/*.py（经 ctx.subprocess，沙箱合规）。返回 {exitCode, stdout, stderr}。 */\nexport async function runScript(ctx, script, args = [], opts = {}) {\n  let handle\n  try {\n    handle = ctx.subprocess.spawn({\n      argv: [opts.python ?? 'python', join(SCRIPTS_DIR, script), ...args],\n      cwd: REPO_ROOT,\n      env: opts.env ?? {}, // 只传增量：运行时自带清洗后的父环境基线，勿展开 ...process.env\n      graceMs: opts.graceMs ?? 3000,\n      stdio: {\n        stdin: opts.stdinData !== undefined ? { data: opts.stdinData } : 'ignore',\n        stdout: { maxBytes: opts.maxBytes ?? 2_000_000 },\n        stderr: { maxBytes: opts.maxBytes ?? 2_000_000 },\n      },\n    })\n  } catch (err) {\n    return { exitCode: 2, stdout: '', stderr: `❌ 无法启动脚本（python 是否在 PATH？）: ${err?.message ?? err}` }\n  }\n  const { exitCode } = await handle.done\n  return {\n    exitCode: exitCode ?? 1,\n    stdout: (handle.collected?.stdout?.readFrom(0)?.text ?? '').trim(),\n    stderr: (handle.collected?.stderr?.readFrom(0)?.text ?? '').trim(),\n  }\n}\n\n/** 统一结果包装：脚本返回 → 工具返回。 */\nfunction wrap(r) {\n  return { exit_code: r.exitCode, output: r.stdout, stderr: r.stderr }\n}\n\nexport function apply(ctx, config) {\n  // config 可能为 undefined（agent.cordis.yml 的 gzhflow-tools 行无 config 块时 cordis 传 undefined）\n  const pythonBin = config?.python ?? 'python'\n  const registerTool = (tool) => ctx.effect(() => ctx.tools.register({\n    ...tool,\n    parameters: toJsonSchema(tool.parameters),\n  }))\n\n  // 首次使用环境自检：会话开始第一步调用。只返回「已配置/缺失」状态，绝不返回凭据值。\n  registerTool({\n    name: 'gzhflow_check_env',\n    description: 'gzhflow 环境自检（会话开始第一步）：检查公众号发布凭据（必填）与图生后端（选填）配置状态，返回结构化结果与引导建议。只返回是否已配置，不返回任何凭据值。',\n    parameters: {},\n    output: { schema: { type: 'object' }, render: (_a, v) => [{ type: 'text', text: JSON.stringify(v, null, 2) }] },\n    async execute() {\n      const credentials = ctx.get('credentials')\n      const read = async (ref) => {\n        if (credentials) {\n          const res = await credentials.resolve(ref)\n          if (res?.value !== undefined && res?.value !== '') return true\n        }\n        return !!(process.env[ref] && process.env[ref].length > 0)\n      }\n      const wechatId = await read('WECHAT_APP_ID')\n      const wechatSecret = await read('WECHAT_APP_SECRET')\n      const backend = readImageBackendConfig()\n      const keyName = backend.api_key_env || 'IMAGE_API_KEY'\n      const imageKey = await read(keyName)\n      const wechatReady = wechatId && wechatSecret\n      const backendReady = !!(backend.base_url && backend.model)\n      const imageReady = backendReady && imageKey\n\n      const wechatMissing = []\n      if (!wechatId) wechatMissing.push('WECHAT_APP_ID')\n      if (!wechatSecret) wechatMissing.push('WECHAT_APP_SECRET')\n      const imageMissing = []\n      if (!backendReady) imageMissing.push('image_backend.base_url/model（config/workflow.yaml）')\n      if (!imageKey) imageMissing.push(keyName)\n\n      let recommendation\n      if (!wechatReady) {\n        recommendation = '❌ 公众号凭据未配置（必填）：请编辑 ~/.dsh/.credentials.yaml 添加 ' +\n          wechatMissing.join(' 与 ') + '，配置完成前不开始写作流程。'\n      } else if (!imageReady) {\n        recommendation = '⚠️ 图生后端未配置（选填）：④配图将走真实图轨（用户提供素材图，或 web_search 找合规真实图）；' +\n          '如需 AI 生图，配置 config/workflow.yaml 的 image_backend 与 .credentials.yaml 的 ' + keyName + '。'\n      } else {\n        recommendation = '✅ 公众号凭据与图生后端均已配置，可完整跑六阶段。'\n      }\n\n      return {\n        wechat_ready: wechatReady,\n        wechat_missing: wechatMissing,\n        image_generation_ready: imageReady,\n        image_backend_configured: backendReady,\n        image_key_configured: imageKey,\n        image_key_env: keyName,\n        recommendation,\n      }\n    },\n  })\n\n  registerTool({\n    name: 'gzhflow_deai_score',\n    description: 'gzhflow 去 AI 味机器门（ai_flavor_score.py）。exit_code 0=硬禁令清零，1=有 FAIL（必须清零才能交稿）；output 含 FAIL/WARN 明细。',\n    parameters: {\n      text: { type: 'string', description: '待检文本（与 file 二选一）' },\n      file: { type: 'string', description: '稿件 .md 路径（自动剥离 frontmatter 与签名行）' },\n    },\n    output: { schema: { type: 'object' }, render: (_a, v) => [{ type: 'text', text: JSON.stringify(v, null, 2) }] },\n    async execute(args) {\n      if (!args.text && !args.file) return { exit_code: 2, output: '参数错误：text 与 file 必须给一个', stderr: '' }\n      const argv = args.file ? [args.file] : ['--text', args.text]\n      return wrap(await runScript(ctx, 'ai_flavor_score.py', argv, { python: pythonBin }))\n    },\n  })\n\n  registerTool({\n    name: 'gzhflow_check_prompt',\n    description: 'gzhflow 配图 prompt 质检门（check_image_prompt.py）。exit_code 0=PASS（含 WARN 不阻断），1=FAIL（硬规避或必需项缺失）。',\n    parameters: {\n      prompt: { type: 'string', required: true, description: '四段式编译出的图生 prompt 全文' },\n    },\n    output: { schema: { type: 'object' }, render: (_a, v) => [{ type: 'text', text: JSON.stringify(v, null, 2) }] },\n    async execute(args) {\n      if (!args.prompt) return { exit_code: 2, output: '参数错误：prompt 必填', stderr: '' }\n      return wrap(await runScript(ctx, 'check_image_prompt.py', [], { stdinData: args.prompt, python: pythonBin }))\n    },\n  })\n\n  registerTool({\n    name: 'gzhflow_validate_html',\n    description: 'gzhflow 排版 HTML 校验（validate_gzh_html.py）。exit_code 0=0 ERROR 通过，1=有 ERROR（必须清零才能推送）。',\n    parameters: {\n      html: { type: 'string', required: true, description: 'md2wechat 产出的 HTML 全文' },\n    },\n    output: { schema: { type: 'object' }, render: (_a, v) => [{ type: 'text', text: JSON.stringify(v, null, 2) }] },\n    async execute(args) {\n      if (!args.html) return { exit_code: 2, output: '参数错误：html 必填', stderr: '' }\n      return wrap(await runScript(ctx, 'validate_gzh_html.py', ['--stdin'], { stdinData: args.html, python: pythonBin }))\n    },\n  })\n\n  registerTool({\n    name: 'gzhflow_md2wechat',\n    description: 'gzhflow Markdown → 公众号 HTML 转换（md2wechat.py）。返回输出路径（output 首行）。',\n    parameters: {\n      md_path: { type: 'string', required: true, description: '稿件 .md 路径' },\n      theme: { type: 'string', description: '主题名（默认 zen；可选 minimal）' },\n      output: { type: 'string', description: '输出 HTML 路径（默认 <md 同目录>_排版_<主题>.html）' },\n    },\n    output: { schema: { type: 'object' }, render: (_a, v) => [{ type: 'text', text: JSON.stringify(v, null, 2) }] },\n    async execute(args) {\n      const argv = [args.md_path, '--theme', args.theme ?? 'zen']\n      if (args.output) argv.push('-o', args.output)\n      return wrap(await runScript(ctx, 'md2wechat.py', argv, { python: pythonBin }))\n    },\n  })\n\n  registerTool({\n    name: 'gzhflow_generate_image',\n    description: 'gzhflow 图生（generate_image.py，OpenAI 兼容接口）。需先配置图生后端：仓库 config/workflow.yaml 的 image_backend（base_url/model）+ DSH 凭据 IMAGE_API_KEY。exit_code 0=成功，1=API 失败，2=缺 key/配置；output 含保存路径。',\n    parameters: {\n      prompt: { type: 'string', required: true, description: '四段式编译出的图生 prompt' },\n      ratio: { type: 'string', description: '画布比例（默认读 config image_spec.cover_ratio，兜底 16:9）' },\n      size: { type: 'string', description: '直接指定 size（如 1280x720），覆盖比例映射' },\n      output: { type: 'string', required: true, description: '输出图片路径' },\n      n: { type: 'number', description: '生成张数（默认 1）' },\n    },\n    output: { schema: { type: 'object' }, render: (_a, v) => [{ type: 'text', text: JSON.stringify(v, null, 2) }] },\n    async execute(args) {\n      // 图生后端引导：config/workflow.yaml 的 image_backend 段缺失时给可操作指引\n      const backend = readImageBackendConfig()\n      if (!backend.base_url || !backend.model) {\n        return {\n          exit_code: 2,\n          output: '',\n          stderr: '❌ 图生后端未配置：复制仓库 config/workflow.example.yaml 为 config/workflow.yaml，' +\n                  '填写 image_backend.base_url（如 https://dashscope.aliyuncs.com/compatible-mode/v1）与 image_backend.model（如 wanx2.1-t2i-turbo）。',\n        }\n      }\n      // key：DSH 凭据 IMAGE_API_KEY > 环境变量 IMAGE_API_KEY（或 config 里 api_key_env 指定的变量名）\n      const credentials = ctx.get('credentials')\n      const envKeyName = backend.api_key_env || 'IMAGE_API_KEY'\n      const credRes = credentials ? await credentials.resolve(envKeyName) : undefined\n      const apiKey = credRes?.value || process.env[envKeyName] || ''\n      if (!apiKey) {\n        return {\n          exit_code: 2,\n          output: '',\n          stderr: `❌ 缺图生 API key：请编辑 ~/.dsh/.credentials.yaml 添加 ${envKeyName}: <你的key>（或设同名环境变量）。`,\n        }\n      }\n      const argv = ['--prompt', args.prompt, '-o', args.output]\n      if (args.ratio) argv.push('--ratio', args.ratio)\n      if (args.size) argv.push('--size', args.size)\n      if (args.n && args.n > 1) argv.push('--n', String(args.n))\n      const r = await runScript(ctx, 'generate_image.py', argv, { env: { [envKeyName]: apiKey }, python: pythonBin })\n      return wrap(r)\n    },\n  })\n\n  registerTool({\n    name: 'gzhflow_publish_draft',\n    description: 'gzhflow 推草稿箱（publish_draft.py，微信官方 API）。凭证从 DSH 凭据存储读取（WECHAT_APP_ID / WECHAT_APP_SECRET），经 env 注入，不进命令行参数。建议先 dry_run=true 验证。',\n    parameters: {\n      html: { type: 'string', required: true, description: '排版 HTML 路径' },\n      title: { type: 'string', required: true, description: '文章标题' },\n      author: { type: 'string', description: '作者（默认 frontmatter > config > 空）' },\n      summary: { type: 'string', description: '摘要（默认截取正文前 120 字）' },\n      cover: { type: 'string', description: '封面图路径（默认读 frontmatter coverImage）' },\n      dry_run: { type: 'boolean', description: 'true=只验证不推送（不取 token）' },\n    },\n    output: { schema: { type: 'object' }, render: (_a, v) => [{ type: 'text', text: JSON.stringify(v, null, 2) }] },\n    async execute(args) {\n      const argv = [args.html, '--title', args.title]\n      if (args.author) argv.push('--author', args.author)\n      if (args.summary) argv.push('--summary', args.summary)\n      if (args.cover) argv.push('--cover', args.cover)\n      if (args.dry_run) argv.push('--dry-run')\n      const env = {}\n      if (!args.dry_run) {\n        // dry_run 免凭证（与脚本一致：dry-run 在 load_credentials 前返回）\n        const credentials = ctx.get('credentials')\n        const read = async (ref) => {\n          const res = credentials ? await credentials.resolve(ref) : undefined\n          return res?.value\n        }\n        const appId = await read('WECHAT_APP_ID')\n        const appSecret = await read('WECHAT_APP_SECRET')\n        if (!appId || !appSecret) {\n          return { exit_code: 2, output: '', stderr: '❌ 未配置公众号凭证：请编辑 ~/.dsh/.credentials.yaml 添加 WECHAT_APP_ID 与 WECHAT_APP_SECRET（详见 dsh-preset/README.md「凭证」）' }\n        }\n        env.WECHAT_APP_ID = appId\n        env.WECHAT_APP_SECRET = appSecret\n      }\n      const r = await runScript(ctx, 'publish_draft.py', argv, { env, python: pythonBin })\n      return wrap(r)\n    },\n  })\n}\n"
    },
    {
      "path": "dsh-preset/tools/gzhflow-skill.mjs",
      "content": "/**\n * gzhflow-skill — 把 gzhflow 六阶段工作流 skill 作为「bundled」provider 注册进\n * DeepSeek Harness 的 ctx.skills 注册表，使 `dsh plugin add` 安装后无需任何\n * 文件拷贝即可被 skill 系统发现、加载。\n *\n * 零运行时依赖（只用 node: 内建），不 import @deepseek-ai/*（服务经 inject 注入）。\n * 与 gzhflow-tools.mjs 解耦：即使 skill 目录缺失，本模块也静默降级（list 返回空），\n * 不影响工具注册。\n *\n * DSH plugin 模块契约：export const name / inject / apply(ctx, config)。\n */\nimport { fileURLToPath } from 'node:url'\nimport { join } from 'node:path'\nimport { readFileSync, existsSync } from 'node:fs'\n\nexport const name = 'gzhflow-skill'\nexport const inject = ['skills']\n\n// 模块位于 <pkg>/dsh-preset/tools/ → 打包的 skill 目录在 <pkg>/skills/gzhflow\nconst SKILL_DIR = fileURLToPath(new URL('../../skills/gzhflow/', import.meta.url))\nconst SKILL_MD = join(SKILL_DIR, 'SKILL.md')\n\n// @deepseek-ai/dsh-skill 的 BUNDLED_SKILL_RANK：打包 provider 的标准优先级。\nconst BUNDLED_SKILL_RANK = 600\nconst INVOCATION = { modelInvocable: true, userInvocable: true }\nconst RESOURCE_BASE = { kind: 'directory', path: SKILL_DIR }\n\nconst FALLBACK_DESCRIPTION =\n  '跨 Agent 公众号内容发布工作流（六阶段，带质量门）。'\n\n/** 极简 YAML frontmatter 解析（skill 头只需 name/description 等纯键值）。 */\nfunction parseFrontmatter(text) {\n  const m = /^---\\r?\\n([\\s\\S]*?)\\r?\\n---\\r?\\n?/.exec(text)\n  if (!m) return { body: text, meta: {} }\n  const meta = {}\n  for (const line of m[1].split(/\\r?\\n/)) {\n    const kv = /^([A-Za-z0-9_-]+):\\s*(.*)$/.exec(line)\n    if (kv) meta[kv[1]] = kv[2].trim()\n  }\n  return { body: text.slice(m[0].length), meta }\n}\n\n/** 读取并解析 SKILL.md（惰性，跟随文件改动；缺失返回 null）。 */\nfunction readSkill() {\n  let text\n  try {\n    text = readFileSync(SKILL_MD, 'utf8')\n  } catch {\n    return null\n  }\n  const { body, meta } = parseFrontmatter(text)\n  return { body, meta }\n}\n\nconst skillAtLoad = readSkill()\nconst DESCRIPTION = typeof skillAtLoad?.meta?.description === 'string'\n  ? skillAtLoad.meta.description\n  : FALLBACK_DESCRIPTION\n\nconst provider = {\n  name: 'gzhflow',\n  async list() {\n    if (!existsSync(SKILL_MD)) return []\n    return [{\n      name: 'gzhflow',\n      description: DESCRIPTION,\n      rank: BUNDLED_SKILL_RANK,\n      locator: SKILL_MD,\n      path: SKILL_MD,\n      metadata: skillAtLoad?.meta,\n      source: 'bundled',\n      provider: 'gzhflow',\n      invocation: INVOCATION,\n      resourceBase: RESOURCE_BASE,\n    }]\n  },\n  async get() {\n    const s = readSkill()\n    if (!s) return undefined\n    return {\n      name: 'gzhflow',\n      description: DESCRIPTION,\n      content: s.body,\n      path: SKILL_MD,\n      metadata: s.meta,\n      source: 'bundled',\n      provider: 'gzhflow',\n      invocation: INVOCATION,\n      resourceBase: RESOURCE_BASE,\n    }\n  },\n}\n\nexport function apply(ctx) {\n  if (!ctx.skills || typeof ctx.skills.registerProvider !== 'function') return\n  ctx.effect(() => ctx.skills.registerProvider(() => provider))\n}\n"
    },
    {
      "path": "scripts/ai_flavor_score.py",
      "content": "#!/usr/bin/env python3\n\"\"\"gzhflow 去 AI 味质检门（ai_flavor_score）。\n\n出稿后跑一遍，FAIL 项必须清零，WARN 项是体检报告，人看。\n规则依据来自两处：一是本项目自己攒的踩坑经验，二是 larashero3-dotcom/lieflat-less-ai-tone\n（MIT）那篇对照语料研究——629 篇文章 283 万字，5 个模型各 60 篇对 329 篇人类文本，\n26 项候选特征逐项算频率比 R = 生成侧 ÷ 人类侧。本文件里带 R 的注释都出自它。\n\n三条已按那项研究撤掉的规则（曾在本文件里，2026-10-12 删）：\n  句长变异系数 CV < 0.3 —— 实测 R=0.87，生成 0.58 / 人类 0.67，无区分力\n  句内同构排比 —— 实测 R=0.61，人类用得比 AI 还多\n  比喻/隐喻整体 —— 实测 R=0.42，人类是 AI 的 2.4 倍\n\n用法:\n    python scripts/ai_flavor_score.py <稿件.md>       # 检文件（自动剥离 frontmatter）\n    python scripts/ai_flavor_score.py --text \"文本\"    # 检直接传入的文本\n    python scripts/ai_flavor_score.py --model deepseek <稿件.md>\n    python scripts/ai_flavor_score.py - < 稿件.md      # 检 stdin\n\n--model 只影响破折号的阈值。破折号这项模型间极差 40 倍\n（DeepSeek 5.16 次/千字，Claude 4.25，Kimi 2.32，Gemini 0.51，GPT 只有 0.11，\n人类 0.80），一刀切禁它对 GPT 输出是在删一个比人用得还少的标点。\n不指定时用生成侧整体均值 2.38。\n\n退出码: 0 = 无 FAIL, 1 = 有 FAIL（必须清零后才能交稿）\n文体分流：draft.md frontmatter 写 genre: 抒情 / 说理 / 测评，抒情类跳过数字密度提示。\n\"\"\"\nimport argparse\nimport re\nimport sys\nfrom collections import Counter\n\n# Windows GBK 控制台兼容：强制 UTF-8 输出\nif hasattr(sys.stdout, \"reconfigure\"):\n    sys.stdout.reconfigure(encoding=\"utf-8\", errors=\"replace\")\n\n# 各模型破折号频率（次/千字），来自 lieflat 的实测表\nMODEL_DASH = {\n    \"gpt\": 0.11, \"gemini\": 0.51, \"kimi\": 2.32,\n    \"claude\": 4.25, \"deepseek\": 5.16,\n}\nDASH_HUMAN = 0.80      # 人类侧基准\nDASH_DEFAULT = 2.38    # 未指定模型时用生成侧整体均值\n\n# FAIL：命中必须清零。\n# 2026-10-12 收窄过一次。此前翻案句、拟人化喻体、黑话、破折号也在这里，\n# 结果拿作者本人写的四段范文跑了一遍，四段里三段被 FAIL——全是误杀：\n#   「绝不是断层的色带，而是混合交织的多彩」被判翻案句（这是他写得最好的一句）\n#   破折号每千字 1.65 次被判超阈值（那是他的个人习惯，通用人类基准只有 0.80）\n#   「AI占据了自己的生态位」被判黑话（这里是准确的专业词，不是模型腔）\n# 所以立了条规矩：门如果拦作者本人，它就是错的。现在只留两项纯模型腔词汇，\n# 人类几乎不用，误杀率最低。其余全部降为 WARN，看报告自己判断。\nHARD_BANS = {\n    # 一开口就是\"值得注意的是\"，读者立刻知道不是人写的\n    \"模型路标\": re.compile(r\"值得注意的是|需要指出的是|更微妙的是|不难发现|显而易见|\"\n                           r\"总的来说|归根结底|换言之|换句话说|值得一提的是\"),\n\n    # 段首起首语，R=3.2。说白了/说到底同时归这里和下面的段首零回指\n    \"起首语\": re.compile(r\"说白了|说穿了|先说结论|言归正传|总而言之|综上所述\"),\n}\n\n# WARN：体检报告项，不拦稿，人看了自己判断。带 R 的是 lieflat 实测通过的。\n# 翻案句 / 拟人化喻体 / 黑话三项 2026-10-12 从 FAIL 降到这里——实测会误杀作者本人，\n# 详见 HARD_BANS 上方的说明。\nWARN_ITEMS = {\n    # 对举结构，R=3.4。人类侧也有 0.22/千字，是正常的转折强调，\n    # 只在连续出现多处时才值得警惕\n    \"翻案句\": re.compile(\n        r\"不是[^。！？]{2,20}而是|并非[^。！？]{2,20}而是|\"\n        r\"不在于[^。！？]{2,20}而在于|与其说[^。！？]{2,20}不如说|\"\n        r\"表面[^。！？]{2,20}其实|看似[^。！？]{2,20}实则|\"\n        r\"看似[^。！？]{2,20}实际上\"),\n\n    # 拟人化喻体，R=7.3，区分力最强的一项。禁的不是比喻本身（人类比 AI 更爱比喻），\n    # 禁的是\"像一位智慧的导师\"\"一个永不疲倦的初级审查员\"这种理想化职业人格\n    \"拟人化喻体\": re.compile(\n        r\"(?:像|就像|好比|好像|仿佛|如同|好似)[^。]{0,14}\"\n        r\"(导师|审查员|侦探|律师|医生|老师|工程师|会计|管家|助手|伙伴|\"\n        r\"向导|引路人|灯塔|舵手|守门人|裁判|教练|工匠|园丁|建筑师|\"\n        r\"观察者|记录者|叙事者|策展人)\"),\n\n    # 黑话。语境准就留——\"占据生态位\"里的生态位是专业词，不是模型腔\n    \"黑话（模型腔）\": re.compile(\n        r\"赋能|抓手|闭环|底层逻辑|顶层设计|降本增效|全链路|组合拳|\"\n        r\"商业闭环|护城河|第二曲线|心智|赛道|生态位|势能\"),\n\n    # 冒号。以前是一刀切 FAIL，把\"时间：2024年秋天\"一起杀了。\n    # 实测有区分力的是提示性冒号（R=3.8）和空转句引列表（R=9.4），其余冒号无区分力。\n    # 这里只查这两种：段首/段中挂着程度副词然后冒号引出解释，以及\"如下/包括\"这类空转引列表。\n    \"提示性冒号\": re.compile(\n        r\"[^。！？\\n]{0,10}(?:很|太|最|更|特别|尤其|真正|其实|往往|通常|真的|\"\n        r\"确实|显然|明显|事实上)[^。！？\\n]{0,8}[：:]\"),\n    \"空转列表冒号\": re.compile(r\"(如下|包括|分为|有以下|以下几|三类|三种|两步)[：:]\"),\n\n    # 段首零回指评论，R=4.4，全场区分力最强，而本项目此前完全没有这项。\n    # 新段落开口就下评价，不说是评谁，读者得翻回上一段才知道在讲什么。\n    # 修法很轻：补一个\"这/那\"把上文接回来。\n    \"段首零回指评论\": re.compile(\n        r\"^(?:听起来|看起来|看上去|听上去|说白了|说到底|换句话说|意味着|值得注意|\"\n        r\"不难看出|细看|再看|回过头看|问题在于|原因在于|结果是|有意思的是|\"\n        r\"更重要的是|关键在于|真正的)\"),\n    # 段首带了回指成分的（这/那/其/以上/但/所以…）不算，那是正常衔接\n    \"段首有回指\": re.compile(\n        r\"^(?:这|那|其|此|上面|前面|刚才|以上|该|它|他|她|它们|他们|同样|类似|\"\n        r\"相比|反过来|但|不过|所以|因此|于是|而|另|除此|与此)\"),\n\n    # 相邻句结构同构，R=2.0。注意不是句内排比——句内排比人类用得更多。\n    # 指纹取（逗号数, 有无冒号, 有无括号, 长度档），段内连续两句指纹相同且都有逗号才算。\n    \"相邻句同构\": None,   # 特殊处理，见 detect_adjacent_isomorphic\n\n    # 顿号并列过密，R=1.8\n    \"顿号并列过密\": re.compile(r\"[，、][^，。！？]{1,12}(?:、[^，。！？]{1,12}){3,}\"),\n\n    # 序数词充当小标题，R=3.1。\n    # 注意：排版主题若自带编号章节（红白主题就是），最终 HTML 的编号是排版加的，\n    # 不算 AI 味；这里只反映 md 原文里 AI 自己写的序号标题。\n    \"序数词小标题\": re.compile(r\"^(?:0[1-9]|[1-9][0-9]?)[、.． ]\"),\n\n    # 译文句式 5 项，R=2.6~5.3。全是英文句法直接移植的产物\n    \"当…时从句\": re.compile(r\"当[^。]{2,30}时\"),\n    \"前置话题壳\": re.compile(r\"对于[^。]{2,20}来说\"),\n    \"句首连接词\": re.compile(r\"^(然而|因此|此外|与此同时)[，,]\"),\n    \"这意味着复述句\": re.compile(r\"这意味着\"),\n    \"过长前置定语\": re.compile(r\"的[^。！？，、；]{1,18}的[^。！？，、；]{1,18}的\"),\n\n    \"抒情词（≥2 处）\": re.compile(r\"安放|抵达|微光|褶皱|滚烫|斑驳|葳蕤|缱绻|呢喃|氤氲\"),\n    \"语境黑话（本义准就留）\": re.compile(r\"沉淀|颗粒度|对齐|方法论\"),\n    \"翻案腔变形\": re.compile(r\"以为[^。！？]{2,20}其实|回头才发现|真正[^。！？]{2,20}的是|不只[^。！？]{2,20}还\"),\n    \"名词化句式\": re.compile(r\"进行了[^。]{1,10}|实现了[^。]{1,10}提升|完成了对[^。]{1,10}的\"),\n    \"重复开头词（同词开头 ≥3 段）\": None,   # 特殊处理\n}\n\n# 连词密度（WARN）：常见过渡连词\nCONJUNCTION_RE = re.compile(\n    r\"但是|然而|因此|所以|而且|不过|并且|因为|虽然|如果|于是|同时|此外|可是|总之\")\n\nDASH_RE = re.compile(r\"[—–]\")\n\n\ndef strip_frontmatter(text):\n    \"\"\"剥离 YAML frontmatter（--- 块）。\"\"\"\n    if text.startswith(\"---\"):\n        parts = text.split(\"---\", 2)\n        if len(parts) >= 3:\n            return parts[2]\n    return text\n\n\ndef strip_signature(text):\n    \"\"\"剥离落款签名行（如「—— 作者名」），破折号是签名格式，不进去凑数。\"\"\"\n    lines = text.splitlines()\n    kept = [ln for ln in lines if not re.match(r\"^\\s*[—–]\\s*\\S\", ln)]\n    return \"\\n\".join(kept)\n\n\ndef read_genre(raw):\n    \"\"\"从 frontmatter 读 genre 字段，用于按文体分流。\n\n    在 draft.md 的 frontmatter 里写 genre: 抒情 / 说理 / 测评，\n    抒情类会跳过\"数字偏少\"提示——散文里没数字是正常的。\n    \"\"\"\n    m = re.search(r\"^genre\\s*[:=]\\s*(.+)\", raw, re.M)\n    if not m:\n        return \"\"\n    return m.group(1).strip().strip(\"\\\"'\")\n\n\ndef sentence_signature(sent):\n    \"\"\"句子结构指纹：逗号数、有无冒号、有无括号、长度档。\"\"\"\n    return (sent.count(\"，\"), \"：\" in sent,\n            (\"（\" in sent or \"(\" in sent), len(sent) // 15)\n\n\ndef detect_adjacent_isomorphic(paras):\n    \"\"\"段内连续两句结构指纹相同且都带逗号 —— 比\"句内排比\"更接近 AI 的实际毛病。\"\"\"\n    hits = []\n    for para in paras:\n        body = re.sub(r\"^[#>\\-\\*\\d\\.、\\s]+\", \"\", para)\n        sents = [s.strip() for s in re.split(r\"[。！？]\", body) if len(s.strip()) > 10]\n        for i in range(len(sents) - 1):\n            a, b = sentence_signature(sents[i]), sentence_signature(sents[i + 1])\n            if a == b and a[0] >= 1:\n                hits.append(sents[i][:14] + \" / \" + sents[i + 1][:14])\n    return hits\n\n\ndef detect_repeat_head(paras):\n    \"\"\"≥3 段用同一个词开头。\"\"\"\n    starts = []\n    for para in paras:\n        m = re.match(r\"^[#>\\-\\*\\d\\.、\\s]*([A-Za-z]+|[\\u4e00-\\u9fff]{2})\", para)\n        if m:\n            starts.append(m.group(1))\n    if not starts:\n        return None\n    word, cnt = Counter(starts).most_common(1)[0]\n    return (word, cnt) if cnt >= 3 else None\n\n\ndef dash_threshold(model):\n    \"\"\"破折号阈值：取\"人类基准\"和\"该模型实际用量的一半\"里的较大值。\n\n    这样对 GPT 这类天生不爱用破折号的模型基本不报，对 DeepSeek 照常抓。\n    \"\"\"\n    rate = MODEL_DASH.get(model, DASH_DEFAULT)\n    return max(DASH_HUMAN, rate * 0.6)\n\n\ndef detect(text, model=None, genre=\"\"):\n    fails, warns = [], []\n\n    for name, pat in HARD_BANS.items():\n        for m in pat.finditer(text):\n            fails.append(\"[FAIL] %s: 「%s」\" % (name, text[max(0, m.start() - 8):m.end() + 8]))\n\n    for name, pat in WARN_ITEMS.items():\n        if pat is None or name == \"段首有回指\":\n            # 段首有回指是\"段首零回指\"的排除条件，不是独立报告项\n            continue\n        if name == \"段首零回指评论\":\n            # 逐段看段首：命中评论语且没有回指成分才算\n            paras = [p.strip() for p in re.split(r\"\\n\\s*\\n\", text) if p.strip()]\n            for para in paras:\n                first = para.split(\"\\n\")[0].strip()\n                if pat.match(first) and not WARN_ITEMS[\"段首有回指\"].match(first):\n                    snippet = first[:24] + (\"…\" if len(first) > 24 else \"\")\n                    warns.append(\"[WARN] 段首零回指评论（R=4.4，全场最强特征，\"\n                                 \"补个「这/那」就能修）: 「%s」\" % snippet)\n            continue\n        if name == \"序数词小标题\":\n            # 只看以标题形式出现的行，正文里提\"第一步\"不算\n            for line in text.splitlines():\n                line = line.strip()\n                if line.startswith(\"#\") or re.match(r\"^\\*\\*\", line):\n                    if pat.match(re.sub(r\"^[#*\\s]+\", \"\", line)):\n                        warns.append(\"[WARN] 序数词小标题（R=3.1）: 「%s」\" % line[:30])\n            continue\n        if name == \"句首连接词\":\n            for line in text.splitlines():\n                line = line.strip()\n                if not line:\n                    continue\n                if pat.match(line):\n                    warns.append(\"[WARN] 句首连接词（R=2.6~5.3）: 「%s」\" % line[:24])\n            continue\n        for m in pat.finditer(text):\n            warns.append(\"[WARN] %s: 「%s」\" % (name, text[max(0, m.start() - 8):m.end() + 8]))\n\n    # 抒情词计数（≥2 才报）\n    lyr = WARN_ITEMS[\"抒情词（≥2 处）\"]\n    lyr_hits = lyr.findall(text)\n    if len(lyr_hits) >= 2:\n        warns.append(\"[WARN] 抒情词 %d 处: %s\" % (len(lyr_hits), \"/\".join(lyr_hits)))\n\n    paras = [p.strip() for p in re.split(r\"\\n\\s*\\n\", text) if p.strip()]\n\n    # 相邻句同构\n    iso = detect_adjacent_isomorphic(paras)\n    if iso:\n        warns.append(\"[WARN] 相邻句同构（R=2.0，%d 处）: %s\"\n                     % (len(iso), \"；\".join(iso[:3])))\n\n    # 重复开头词\n    rep = detect_repeat_head(paras)\n    if rep:\n        warns.append(\"[WARN] 重复开头词: 「%s」作为段首词出现 %d 次\" % rep)\n\n    # 连词密度\n    sentences = [s for s in re.split(r\"[。！？!?]\", text) if s.strip()]\n    if sentences:\n        conj_cnt = len(CONJUNCTION_RE.findall(text))\n        if conj_cnt / len(sentences) > 0.5:\n            warns.append(\"[WARN] 连词密度偏高: %d 个连词 / %d 句\"\n                         % (conj_cnt, len(sentences)))\n\n    # 短段连击\n    if len(paras) >= 3:\n        streak = 0\n        for para in paras:\n            body = re.sub(r\"^[#>\\-\\*\\d\\.、\\s]+\", \"\", para)\n            if len(body) <= 15:\n                streak += 1\n            else:\n                streak = 0\n            if streak >= 3:\n                warns.append(\"[WARN] 短段连击: 连续 ≥3 段过短（每段 ≤15 字，节奏细碎）\")\n                break\n\n    # 破折号。2026-10-12 从 FAIL 降为 WARN：实测作者本人每千字 1.65 次，\n    # 高于通用人类基准 0.80，那是他的个人习惯。拿通用基准卡作者就是卡他的风格。\n    # 阈值照算，但只报告，让人自己跟\"自己平时用多少\"比。\n    plain = text\n    body_chars = len(re.sub(r\"\\s\", \"\", plain))\n    if body_chars >= 200:\n        dashes = len(DASH_RE.findall(plain))\n        per_k = dashes * 1000.0 / body_chars\n        thr = dash_threshold(model)\n        if per_k > DASH_HUMAN:\n            warns.append(\"[WARN] 破折号: 每千字 %.2f 次，人类基准 %.2f，%s 阈值 %.2f。\"\n                         \"跟你自己平时比，别跟通用基准比\"\n                         % (per_k, DASH_HUMAN, model or \"默认\", thr))\n\n    # 数字密度。实测反向：人类每千字 17.92 个数字，生成侧只有 6.34（R=0.35）。\n    # 人类是 AI 的 2.8 倍。数字太少往往意味着写得不够具体。\n    # 抒情类不报——实测作者的抒情样本数字密度是 0.0，硬报会推动人家去散文里塞数据。\n    if body_chars >= 400 and \"抒情\" not in genre:\n        digits = len(re.findall(r\"[0-9０-９]|一两三四五六七八九十百千万亿\", plain))\n        per_k = digits * 1000.0 / body_chars\n        if per_k < 8:\n            warns.append(\"[WARN] 数字偏少: 每千字 %.1f 个，人类基准约 17.9。\"\n                         \"是不是有一段可以落到具体数上？\" % per_k)\n\n    return fails, warns\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=\"gzhflow 去 AI 味质检门\")\n    ap.add_argument(\"path\", nargs=\"?\", help=\"稿件文件路径（- 表示 stdin）\")\n    ap.add_argument(\"--text\", help=\"直接传入文本\")\n    ap.add_argument(\"--model\", help=\"当前用的模型（gpt/gemini/kimi/claude/deepseek），只影响破折号阈值\")\n    args = ap.parse_args()\n\n    genre = \"\"\n    if args.text:\n        text = args.text\n    elif args.path == \"-\":\n        text = sys.stdin.read()\n    elif args.path:\n        raw = open(args.path, encoding=\"utf-8\").read()\n        genre = read_genre(raw)\n        text = strip_frontmatter(raw)\n        text = strip_signature(text)\n    else:\n        ap.print_help()\n        sys.exit(2)\n\n    fails, warns = detect(text, args.model, genre)\n\n    if warns:\n        print(\"⚠️  WARN 项（体检报告，人工判断）:\")\n        for w in warns:\n            print(\"   \", w)\n\n    if fails:\n        print(\"🔴 FAIL: %d 处命中，必须清零后才能交稿:\" % len(fails))\n        for f in fails:\n            print(\"   \", f)\n        sys.exit(1)\n\n    print(\"✅ FAIL 清零，通过\")\n    sys.exit(0)\n\n\nif __name__ == \"__main__\":\n    main()\n"
    },
    {
      "path": "scripts/publish_draft.py",
      "content": "#!/usr/bin/env python3\n\"\"\"gzhflow 推草稿箱工具（publish_draft）。\n\n调用微信官方 API 把排版好的 HTML + 封面图推送到公众号草稿箱：\n  1. 获取 access_token（凭 AppID + AppSecret）\n  2. 上传正文图片（media/uploadimg）→ 重写为 https URL\n  3. 上传封面素材（media/add_material, type=image）\n  4. draft/add 创建草稿\n\n⚠️ 个人主体公众号 2025-07 起无法 API 直接发布（freepublish 回收），\n   本工具只推草稿箱，用户在「公众号助手 App」手动点发布。\n\n凭证读取优先级：命令行参数 → 环境变量 WECHAT_APP_ID/WECHAT_APP_SECRET\n              → config/publish.yaml 的 wechat 字段\n\n用法:\n    python scripts/publish_draft.py <排版.html> --title \"标题\" \\\n        --author \"作者\" --summary \"摘要\" --cover cover.jpg --dry-run\n    python scripts/publish_draft.py <排版.html> --title \"标题\" \\\n        --author \"作者\" --summary \"摘要\" --cover cover.jpg\n\n退出码: 0 = 成功, 非0 = 失败\n\"\"\"\nimport argparse\nimport json\nimport os\nimport re\nimport sys\nimport urllib.request\nimport urllib.error\nfrom pathlib import Path\n\n# Windows GBK 控制台兼容：强制 UTF-8 输出\nif hasattr(sys.stdout, \"reconfigure\"):\n    sys.stdout.reconfigure(encoding=\"utf-8\", errors=\"replace\")\n\nAPI_BASE = \"https://api.weixin.qq.com\"\nROOT = Path(__file__).resolve().parent.parent\n\n\n# ============ 凭证读取 ============\ndef load_credentials(args):\n    app_id = args.app_id or os.environ.get(\"WECHAT_APP_ID\")\n    app_secret = args.app_secret or os.environ.get(\"WECHAT_APP_SECRET\")\n\n    if not app_id or not app_secret:\n        # 兜底：config/publish.yaml\n        cfg = ROOT / \"config\" / \"publish.yaml\"\n        if cfg.exists():\n            text = cfg.read_text(encoding=\"utf-8\")\n            m_id = re.search(r\"app_id\\s*[:=]\\s*[\\\"']?([^\\\"'\\s]+)\", text)\n            m_sec = re.search(r\"app_secret\\s*[:=]\\s*[\\\"']?([^\\\"'\\s]+)\", text)\n            if m_id:\n                app_id = app_id or m_id.group(1)\n            if m_sec:\n                app_secret = app_secret or m_sec.group(1)\n\n    if not app_id or not app_secret:\n        print(\"❌ 缺少凭证：请设环境变量 WECHAT_APP_ID/WECHAT_APP_SECRET 或填 config/publish.yaml\", file=sys.stderr)\n        sys.exit(2)\n    if \"your_\" in app_id or \"your_\" in app_secret or \"REDACTED\" in app_id:\n        print(\"❌ 凭证仍是占位符（your_*/REDACTED），请填入真实 AppID/AppSecret\", file=sys.stderr)\n        sys.exit(2)\n    return app_id, app_secret\n\n\n# ============ API 调用 ============\ndef _die_api_error(e: Exception, context: str) -> None:\n    \"\"\"urllib 网络/HTTP 错误 → 友好信息 + exit(1)，不吐 traceback。\"\"\"\n    if isinstance(e, urllib.error.HTTPError):\n        body = e.read().decode(\"utf-8\", errors=\"replace\")[:300]\n        print(f\"❌ 微信 API HTTP {e.code}（{context}）: {body}\", file=sys.stderr)\n    else:\n        print(f\"❌ 微信 API 网络错误（{context}）: {e.reason}\", file=sys.stderr)\n    sys.exit(1)\n\n\ndef _die_wechat_error(resp: dict, context: str) -> None:\n    \"\"\"微信业务错误 → 40164（IP 白名单）给友好提示，其余给原始响应；exit(1)。\"\"\"\n    errcode = resp.get(\"errcode\")\n    errmsg = str(resp.get(\"errmsg\", \"\"))\n    if errcode == 40164 or \"invalid ip\" in errmsg:\n        print(f\"❌ {context}失败: IP 不在白名单（errcode 40164 invalid ip）。\"\n              f\"请把当前出口 IP 加入「公众号后台 → 设置与开发 → 基本配置 → IP 白名单」\", file=sys.stderr)\n    else:\n        print(f\"❌ {context}失败: {resp}\", file=sys.stderr)\n    sys.exit(1)\n\n\ndef api_get(url: str) -> dict:\n    try:\n        with urllib.request.urlopen(url, timeout=15) as r:\n            return json.loads(r.read().decode(\"utf-8\"))\n    except (urllib.error.HTTPError, urllib.error.URLError) as e:\n        _die_api_error(e, \"api_get\")\n\n\ndef api_post(url: str, data: dict, files: dict = None) -> dict:\n    if files:\n        # multipart 上传素材\n        boundary = \"----gzhflowBoundary\" + os.urandom(8).hex()\n        body = b\"\"\n        for key, (fname, content, ctype) in files.items():\n            body += f\"--{boundary}\\r\\n\".encode()\n            body += f'Content-Disposition: form-data; name=\"{key}\"; filename=\"{fname}\"\\r\\n'.encode()\n            body += f\"Content-Type: {ctype}\\r\\n\\r\\n\".encode()\n            body += content + b\"\\r\\n\"\n        body += f\"--{boundary}--\\r\\n\".encode()\n        req = urllib.request.Request(\n            url, data=body,\n            headers={\"Content-Type\": f\"multipart/form-data; boundary={boundary}\"},\n        )\n    else:\n        req = urllib.request.Request(\n            url, data=json.dumps(data, ensure_ascii=False).encode(\"utf-8\"),\n            headers={\"Content-Type\": \"application/json\"},\n        )\n    try:\n        with urllib.request.urlopen(req, timeout=30) as r:\n            return json.loads(r.read().decode(\"utf-8\"))\n    except (urllib.error.HTTPError, urllib.error.URLError) as e:\n        _die_api_error(e, \"api_post\")\n\n\ndef _content_type(path: Path) -> str:\n    \"\"\"按文件后缀判断上传 Content-Type（.png→image/png、.gif→image/gif，默认 image/jpeg）。\"\"\"\n    return {\n        \".png\": \"image/png\",\n        \".gif\": \"image/gif\",\n        \".jpg\": \"image/jpeg\",\n        \".jpeg\": \"image/jpeg\",\n    }.get(path.suffix.lower(), \"image/jpeg\")\n\n\ndef get_token(app_id: str, app_secret: str) -> str:\n    url = f\"{API_BASE}/cgi-bin/token?grant_type=client_credential&appid={app_id}&secret={app_secret}\"\n    resp = api_get(url)\n    if \"access_token\" not in resp:\n        _die_wechat_error(resp, \"获取 token\")\n    return resp[\"access_token\"]\n\n\n# ============ 上传图片 ============\ndef upload_image(token: str, img_path: Path) -> str:\n    \"\"\"上传正文图片（media/uploadimg），返回 https URL。\"\"\"\n    content = img_path.read_bytes()\n    url = f\"{API_BASE}/cgi-bin/media/uploadimg?access_token={token}\"\n    resp = api_post(url, {}, files={\"media\": (img_path.name, content, _content_type(img_path))})\n    if \"url\" not in resp:\n        _die_wechat_error(resp, \"上传正文图片\")\n    return resp[\"url\"]\n\n\ndef upload_cover(token: str, cover_path: Path) -> str:\n    \"\"\"上传封面为永久素材（material/add_material），返回 media_id（thumb_media_id 用）。\n\n    注意：路径是 /cgi-bin/material/add_material（永久素材），不是 /cgi-bin/media/...\n    （media/ 下没有 add_material，写错会 404）。个人订阅号拥有此基础权限。\n    \"\"\"\n    content = cover_path.read_bytes()\n    url = f\"{API_BASE}/cgi-bin/material/add_material?access_token={token}&type=image\"\n    resp = api_post(url, {}, files={\"media\": (cover_path.name, content, _content_type(cover_path))})\n    if \"media_id\" not in resp:\n        _die_wechat_error(resp, \"上传封面\")\n    return resp[\"media_id\"]\n\n\ndef upload_html_images(token: str, html_text: str, base_dir: Path) -> str:\n    \"\"\"扫描 HTML 中的本地图片，上传并重写为 https URL。\"\"\"\n    def _replace(m):\n        src = m.group(1)\n        if src.startswith((\"http://\", \"https://\", \"data:\")):\n            return m.group(0)\n        p = base_dir / src\n        if not p.exists():\n            print(f\"⚠️ 图片不存在，保留原路径: {src}\", file=sys.stderr)\n            return m.group(0)\n        url = upload_image(token, p)\n        print(f\"  ↳ 上传图片 {src} → {url[:60]}…\")\n        return f'src=\"{url}\"'\n    return re.sub(r'src=\"([^\"]+)\"', _replace, html_text)\n\n\n# ============ 发布偏好（config/publish.yaml 的 publish 段） ============\ndef load_publish_config() -> dict:\n    \"\"\"极简读取 config/publish.yaml 的 publish.default_author / publish.open_comment。\"\"\"\n    cfg = ROOT / \"config\" / \"publish.yaml\"\n    result = {\"default_author\": \"\", \"open_comment\": True}\n    if not cfg.exists():\n        return result\n    text = cfg.read_text(encoding=\"utf-8\")\n    m = re.search(r\"default_author\\s*[:=]\\s*[\\\"']?([^\\\"'\\n]+)\", text)\n    if m:\n        result[\"default_author\"] = m.group(1).strip().strip(\"\\\"'\")\n    m = re.search(r\"open_comment\\s*[:=]\\s*(\\w+)\", text)\n    if m:\n        result[\"open_comment\"] = m.group(1).strip().lower() in (\"true\", \"1\", \"yes\")\n    return result\n\n\n# ============ 主流程 ============\ndef main():\n    ap = argparse.ArgumentParser(description=\"gzhflow 推草稿箱（微信官方 API）\")\n    ap.add_argument(\"html\", help=\"排版 HTML 路径\")\n    ap.add_argument(\"--title\", required=True, help=\"文章标题\")\n    ap.add_argument(\"--author\", help=\"作者（默认 config 或 frontmatter）\")\n    ap.add_argument(\"--summary\", help=\"摘要（默认截取正文前 120 字）\")\n    ap.add_argument(\"--cover\", help=\"封面图路径（2.35:1 ≈ 900x383；缺省读 frontmatter 的 coverImage）\")\n    ap.add_argument(\"--no-cover\", action=\"store_true\", help=\"已废弃：draft/add 强制要求封面 thumb_media_id，无封面必报 40007\")\n    ap.add_argument(\"--app-id\", help=\"AppID（覆盖环境变量）\")\n    ap.add_argument(\"--app-secret\", help=\"AppSecret（覆盖环境变量）\")\n    ap.add_argument(\"--dry-run\", action=\"store_true\", help=\"验证全链路但不推送（取 token 前返回）\")\n    args = ap.parse_args()\n\n    if args.no_cover:\n        print(\"❌ --no-cover 已废弃：draft/add 接口强制要求封面 thumb_media_id，\"\n              \"不带封面必然返回 40007 invalid media_id。请用 --cover 指定封面图\", file=sys.stderr)\n        sys.exit(2)\n\n    html_path = Path(args.html)\n    if not html_path.exists():\n        print(f\"❌ HTML 不存在: {html_path}\", file=sys.stderr)\n        sys.exit(2)\n\n    # 元数据：CLI 参数 > frontmatter（md 侧车文件）\n    html_text = html_path.read_text(encoding=\"utf-8\")\n    author = args.author\n    summary = args.summary\n    title = args.title\n    cover = Path(args.cover) if args.cover else None\n\n    # 侧车 md：优先同名 .md，其次工作流产物 draft.md（两者都在 output_dir 内）\n    md_side = next(\n        (p for p in (html_path.with_suffix(\".md\"), html_path.parent / \"draft.md\") if p.exists()),\n        None,\n    )\n    if md_side:\n        md_text = md_side.read_text(encoding=\"utf-8\")\n        fm = re.search(r\"^---\\s*\\n(.*?)\\n---\", md_text, re.S)\n        if fm:\n            for key, pat in ((\"title\", r\"title\\s*:\\s*(.+)\"),\n                             (\"author\", r\"author\\s*:\\s*(.+)\"),\n                             (\"description\", r\"description\\s*:\\s*(.+)\"),\n                             (\"coverImage\", r\"coverImage\\s*:\\s*(.+)\")):\n                m = re.search(pat, fm.group(1))\n                val = m.group(1).strip() if m else \"\"\n                if not val or val == \"null\":\n                    continue\n                if key == \"title\":\n                    title = title or val\n                elif key == \"author\":\n                    author = author or val\n                elif key == \"description\":\n                    summary = summary or val\n                elif key == \"coverImage\" and cover is None:\n                    cover = html_path.parent / val\n\n    if cover is None:\n        print(\"❌ 未指定封面：请用 --cover，或在 frontmatter 写 coverImage\"\n              \"（draft/add 强制要求封面 thumb_media_id，无封面报 40007）\", file=sys.stderr)\n        sys.exit(2)\n    if not cover.exists():\n        print(f\"❌ 封面不存在: {cover}\", file=sys.stderr)\n        sys.exit(2)\n\n    # 作者兜底：--author > frontmatter author > config/publish.yaml 的 publish.default_author > 空\n    pub_cfg = load_publish_config()\n    if not author:\n        author = pub_cfg[\"default_author\"] or \"\"\n\n    if args.dry_run:\n        print(\"✅ dry-run 通过：参数/文件就绪（未取 token，零风险）\")\n        print(f\"   title: {title}\")\n        print(f\"   author: {author or '(未指定)'}\")\n        print(f\"   summary: {(summary or '')[:60]}{'…' if summary and len(summary) > 60 else ''}\")\n        print(f\"   cover: {cover}\")\n        sys.exit(0)\n\n    app_id, app_secret = load_credentials(args)\n    token = get_token(app_id, app_secret)\n    print(\"✅ 已获取 access_token\")\n\n    # 上传正文图片并重写\n    html_remote = upload_html_images(token, html_text, html_path.parent)\n    if html_remote != html_text:\n        print(\"✅ 正文图片已上传并重写为 https URL\")\n\n    # 上传封面（material/add_material 永久素材，个人订阅号实测可用，2026-10-13；\n    # 上传失败直接退出——没有 thumb_media_id 的草稿 draft/add 也会被拒 40007）\n    cover_media_id = upload_cover(token, cover)\n    print(f\"✅ 封面已上传: {cover_media_id}\")\n\n    # 摘要兜底：截取正文前 120 字\n    if not summary:\n        text_only = re.sub(r\"<[^>]+>\", \"\", html_remote)\n        summary = re.sub(r\"\\s+\", \"\", text_only)[:120]\n\n    # 创建草稿\n    article = {\n        \"title\": title,\n        \"author\": author or \"\",\n        \"digest\": summary,\n        \"content\": html_remote,\n        \"content_source_url\": \"\",\n        \"need_open_comment\": 1 if pub_cfg[\"open_comment\"] else 0,\n    }\n    if cover_media_id:\n        article[\"thumb_media_id\"] = cover_media_id\n    resp = api_post(f\"{API_BASE}/cgi-bin/draft/add?access_token={token}\", {\"articles\": [article]})\n    if \"media_id\" in resp:\n        print(f\"✅ 已推送到草稿箱: {resp['media_id']}\")\n        print(\"   请在「公众号助手 App → 草稿箱」检查后手动发布（个人号无法 API 直接发布）\")\n        sys.exit(0)\n    _die_wechat_error(resp, \"创建草稿\")\n\n\nif __name__ == \"__main__\":\n    main()\n"
    },
